fn check_below_threshold(l: Vec<i8>, t: i8) -> bool {
    // For each element x in the vector, check that x is strictly less than t.
    // .all(...) returns true if the iterator is empty (vacuously true) or
    // if the predicate holds for every element.
    l.iter().all(|&x| x < t)
}

